def px(x,y):
 i=(y*w+x)*3; return d[i],d[i+1],d[i+2]
rows={}
for y in range(306,396):
 xs=[]
 for x in range(155,270):
  r,g,b=px(x,y)
  if (r+g)/2>55 and b<g*0.85 and r>40: xs.append(x)
 if xs: rows[y]=(min(xs),max(xs))
# build target points in normalized coordinate bbox x 171..251 (w80), y310..391 (h81)
targets=[]
for y in range(310,392):
 if y in rows:
  a,b=rows[y]
  # use right boundary; y from tip center = 310
  targets.append((y-310, (b-171)))
# center y of rightmost tip ~40.5. For upper half y<=40; lower y>40 left side? We only need top-right.
upper=[(y,x) for y,x in targets if 0<=y<=40.5]
lower=[(y, (171-a)) for y,(a,b) in ((y,rows[y]) for y in range(310,392) if y in rows) if 40.5<y<=81]
# normalized target at each y; mirror left boundary offsets for lower? For fitting top-right only use upper.
def curve_points(p1,p2,n=600):
 pts=[]
 for i in range(n+1):
  t=i/n; u=1-t
  x=u**3*40+3*u*u*t*p1[0]+3*u*t*t*p2[0]+t**3*80
  y=u**3*0+3*u*u*t*p1[1]+3*u*t*t*p2[1]+t**3*40.5
  pts.append((x,y))
 return pts
def err(p1,p2):
 pts=curve_points(p1,p2,400)
 # sort by y; should be monotonic mostly
 e=0
 for y,x in upper:
  # linear interpolate x at y among consecutive pts
  found=None
  for i in range(len(pts)-1):
   y0=pts[i][1]; y1=pts[i+1][1]
   if (y0-y)*(y1-y)<=0 and y0!=y1:
    t=(y-y0)/(y1-y0); found=pts[i][0]+t*(pts[i+1][0]-pts[i][0]);break
  if found is not None: e+=(found-x)**2
 return e
best=(1e18,None)
# random then coordinate refine
for it in range(300000):
 p1=(random.uniform(40,60),random.uniform(0,35))
 p2=(random.uniform(40,80),random.uniform(5,45))
 e=err(p1,p2)
 if e<best[0]: best=(e,(p1,p2))
print('random best',best)
e,(p1,p2)=best
step=4
for rounds in range(40):
 improved=False
 for i in range(2):
  for delta in (-step,step):
   q1=list(p1);q2=list(p2)
   if i==0:q1[0]=min(79,max(40,q1[0]+delta))
   if i==1:q1[1]=min(40,max(0,q1[1]+delta))
   if i==2:q2[0]=min(80,max(40,q2[0]+delta))
   if i==3:q2[1]=min(40,max(0,q2[1]+delta))
   ee=err(tuple(q1),tuple(q2))
   if ee<e:
    e=ee;p1=tuple(q1);p2=tuple(q2);improved=True
 if not improved:
  step*=.6
  if step<.01:break
print('refined',e,p1,p2)
# show error stats at key y
